changeSet.sql:
UPDATE vaccine_brands vb
SET currency = f.default_currency
FROM facility f
WHERE f.id = vb.facility_id;

CREATE OR REPLACE FUNCTION fn_facility_currency_to_vaccine_brands()
RETURNS TRIGGER
AS
$$
BEGIN
  UPDATE vaccine_brands
     SET currency = NEW.default_currency
   WHERE facility_id = NEW.id;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_facility_currency_to_vaccine_brands ON facility;
CREATE TRIGGER trg_facility_currency_to_vaccine_brands
  AFTER UPDATE OF default_currency ON facility
  FOR EACH ROW
  WHEN (OLD.default_currency IS DISTINCT FROM NEW.default_currency)
  EXECUTE FUNCTION fn_facility_currency_to_vaccine_brands();

CREATE OR REPLACE VIEW reports.vwvaccine AS SELECT v.id, v.name, v.atc_code, v.type, v.roa, v.site_of_administration, v.post_opening_duration, v.duration_unit, v.number_of_doses, v.indications, v.possible_reactions, v.contraindications_and_precautions, v.storage_and_handling, v.is_active, v.created_by, v.created_date, v.last_modified_by, v.last_modified_date FROM public.vaccine v;
CREATE OR REPLACE VIEW reports.vwvaccinebrands AS SELECT vb.id, vb.vaccine_id, vb.name, vb.manufacture, vb.volume, vb.unit, vb.marketing_authorization_holder, vb.facility_id, vb.price, vb.currency, vb.is_active, vb.created_by, vb.created_date, vb.last_modified_by, vb.last_modified_date FROM public.vaccine_brands vb;
GRANT SELECT ON reports.vwvaccine TO report_user; GRANT SELECT ON reports.vwvaccinebrands TO report_user;

preConditions.sqlCheck:
SELECT COUNT(*) FROM (
  SELECT 1 FROM vaccine GROUP BY name, type, roa HAVING COUNT(*) > 1
) d
